var n=`1227-lechon-asado`;var r=`world-1227`;var a=`CU`;var o=`central-america-caribbean`;var t=4;var s=310;var d={en:`Lechón Asado`,ua:`Лечон асадо`};var u={en:`Lechón Asado is a dish from Cuba featuring pork shoulder, orange juice, lime juice, garlic. This home-sized recipe records each ingredient at the step where it is used. Oven-roasted lechón uses pork shoulder rather than a whole suckling pig.`,ua:`Лечон асадо, страва кухні країни Куба з такими основними складниками: свиняча лопатка, апельсиновий сік, сік лайма, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Лечон запікається вдома зі свинячої лопатки замість цілого поросяти.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 150 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 150 хвилин.`,t:[`marinating`],m:150,i:[[`pork-shoulder`,1200,`g`],[`orange-juice`,190,`ml`],[`lime-juice`,80,`ml`],[`garlic`,8,`clove`],[`dried-oregano`,8,`g`],[`ground-cumin`,6,`g`]]},{en:`Roast in a preheated 190°C oven for about 145 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 145 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:145,i:[[`olive-oil`,55,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 12 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 12 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:12,i:[[`orange-juice`,90,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`red-onion`,120,`g`]]}];var l={slug:n,id:r,country:`CU`,region:o,servings:4,minutes:310,title:d,text:u,steps:c};export{a as country,l as default,r as id,s as minutes,o as region,t as servings,n as slug,c as steps,u as text,d as title};